import os, glob
roots = ['/home/xlubs/AlphaCrafter', '/home/xlubs', '/tmp', '/home']
seen = set()
for root in roots:
    for dirpath, dirs, files in os.walk(root):
        # skip deep system dirs
        if '/.git' in dirpath or 'site-packages' in dirpath or '__pycache__' in dirpath:
            continue
        for f in files:
            if f.endswith(('.csv','.pkl','.parquet')):
                p = os.path.join(dirpath, f)
                if p in seen: continue
                seen.add(p)
                sz = os.path.getsize(p)
                print(f"{sz:>10} {p}")
        # limit walk depth
        if dirpath.count('/') - root.count('/') > 4:
            dirs[:] = []
